/* Visual explanation of the proposed learning and execution paths. */
const LEARNING_SOURCES={
 R:{title:'Robot action view',caption:'MP4 + TEXT + STATE / ACTION PARQUET',image:'task-start.png',route:'Ảnh/text → VLM features · State → Action Expert · Action targets → loss',limit:'Recorded robot và sim-generated execution dùng cùng action schema. Augmentation là cách tạo variants, không thêm modality.'},
 V:{title:'Temporal video view',caption:'MP4 + TEXT + TIMESTAMPS',image:'task-start.png',route:'Current context → learned tokens · Future frames → target encoder → auxiliary loss',limit:'Recorded hoặc generated video có timestamps/task text. Thiếu robot actions thì action loss disabled; future alignment cần branch riêng. FOCA còn cần task-mismatched negative pool hợp lệ.'},
 H:{title:'Human motion',caption:'RGB · wrist poses · geometry · masks',image:'human-demo.png',route:'Wrist-motion loss → common head + shared Action Expert',limit:'Human pilot freeze VLM. Wrist pose không là robot joint/contact label.'}
};
const LEARNING_RUN=[
 {title:'Robot nhận đầu vào',tag:'RGB + LỆNH + STATE',visual:'input',body:'Camera và câu lệnh đi vào VLM. State đo được cấp riêng cho Action Expert.',output:'Ảnh đúng thời điểm, instruction và robot state'},
 {title:'VLM tạo biểu diễn',tag:'HÌNH ẢNH → FEATURES',visual:'features',body:'VLM mã hóa điều robot nhìn và được yêu cầu. Features là biểu diễn nội bộ, chưa phải command.',output:'Features + masks → Action Expert'},
 {title:'Action Expert',tag:'FEATURES + STATE → ACTION',visual:'action',body:'Dùng features, state và embodiment để tạo chuỗi hành động theo native robot profile.',output:'Normalized action chunk → binding'},
 {title:'Controller thực thi',tag:'ACTION → COMMAND → RESPONSE',visual:'robot',body:'Binding đổi units/order/normalization; controller thực thi. Scorer độc lập chấm cả task.',output:'Command, measured response và task outcome'}
];
function learningVisual(kind,image='task-start.png'){
 if(kind==='alignment')return `<svg viewBox="0 0 320 200" aria-hidden="true"><rect width="320" height="200" fill="#eef3fb"/>${[53,207].map((x,j)=>Array.from({length:8},(_,i)=>`<rect x="${x+i%2*27}" y="${43+Math.floor(i/2)*25}" width="19" height="16" rx="4" fill="${['#416d95','#8ba7c1','#b6cadc','#5b82a5'][(i+j)%4]}"/>`).join('')).join('')}<path d="M118 87H198M184 78L198 87L184 96" fill="none" stroke="#6e8da8" stroke-width="3"/><text x="78" y="158" text-anchor="middle" fill="#456480" font-size="10" font-family="Arial">CURRENT</text><text x="233" y="158" text-anchor="middle" fill="#456480" font-size="10" font-family="Arial">FUTURE TARGET</text><text x="160" y="185" text-anchor="middle" fill="#456480" font-size="10" font-family="Arial">EMBEDDING ALIGNMENT · TRAIN ONLY</text></svg>`;
 if(kind==='input'||kind==='robot')return `<img src="assets/story/${kind==='robot'?'task-success.png':image}" alt="${kind==='robot'?'Robot đặt vật vào khay':'Đầu vào thao tác'} · hình minh họa" width="1672" height="941">`;
 if(kind==='features')return `<svg viewBox="0 0 320 200" aria-hidden="true"><rect width="320" height="200" fill="#eef3fb"/><path d="M35 50H285M35 150H285" stroke="#c3d0e2" stroke-dasharray="4 5"/>${Array.from({length:24},(_,i)=>`<rect x="${64+i%6*33}" y="${43+Math.floor(i/6)*30}" width="23" height="21" rx="5" fill="${['#234e77','#86a7c6','#c2d2e3','#567d9f'][i%4]}" opacity="${.65+(i%3)*.15}"/>`).join('')}<text x="160" y="184" text-anchor="middle" fill="#456480" font-size="11" font-family="Arial">VISION + LANGUAGE FEATURES</text></svg>`;
 if(kind==='checkpoint')return `<svg viewBox="0 0 320 200" aria-hidden="true"><rect width="320" height="200" fill="#eff6f2"/><rect x="102" y="35" width="116" height="123" rx="14" fill="white" stroke="#8aaf9d"/><path d="M129 48H191V80H129ZM129 116H191" fill="#d8e8df" stroke="#5b8a73" stroke-width="3"/><path d="M143 100L155 112L180 87" fill="none" stroke="#3f8061" stroke-width="4"/><text x="160" y="183" text-anchor="middle" fill="#52705e" font-size="11" font-family="Arial">CHECKPOINT + RECIPE</text></svg>`;
 return `<svg viewBox="0 0 320 200" aria-hidden="true"><rect width="320" height="200" fill="#fbf0f1"/>${[50,90,130,170].map(y=>`<path d="M35 ${y}H285" stroke="#ecd9dc"/>`).join('')}<path d="M40 151C76 149 62 122 100 124S132 76 159 89S194 59 221 69S258 39 283 45" stroke="#bd2235" stroke-width="4" fill="none"/>${[[40,151],[100,124],[159,89],[221,69],[283,45]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="#bd2235" stroke="white" stroke-width="2"/>`).join('')}<text x="160" y="187" text-anchor="middle" fill="#935a66" font-size="11" font-family="Arial">ACTION CHUNK · T → T + HORIZON</text></svg>`;
}
function renderLearningCore(){return head('SOLUTION · CÁCH ROBOT HỌC','Từ điều robot nhìn thấy<br>đến hành động cần thực hiện.','Data Core cấp dữ liệu có targets/masks; Model AI học và tạo actions. Hai luồng riêng: training cập nhật weights, inference điều khiển robot.')+`<div class="blue-links"><a href="#engine">Model Engine Core · FluxVLA: training → eval → robot thật →</a></div>`+
 `<section class="learn-workbench"><div class="learn-toolbar"><div class="learn-mode" role="group" aria-label="Luồng cần xem"><button type="button" data-learn-mode="run" aria-pressed="true">Robot thực hiện</button><button type="button" data-learn-mode="train" aria-pressed="false">Huấn luyện</button></div><span class="learn-note">Thiết kế đề xuất · Hình minh họa</span></div><div id="learn-source-controls" hidden><div class="learn-source-tabs" role="group" aria-label="Training views theo supervision"><button type="button" data-learn-source="R" aria-pressed="true">A · Robot action</button><button type="button" data-learn-source="V" aria-pressed="false">B · Video action-free</button><button type="button" data-learn-source="H" aria-pressed="false">C · Human motion</button></div><p class="learn-note">Pretrained checkpoint có sẵn → task adaptation. B và C là candidate riêng.</p></div><div id="learn-flow" class="learn-flow" role="group" aria-label="Bốn khối của luồng"></div><div id="learn-targets" class="learn-targets" hidden></div><div id="learn-route" class="learn-route"></div><article id="learn-detail" class="learn-detail" aria-live="polite"></article></section>`+
 `<div class="blue-links"><a href="#sources">File formats & supervision →</a><a href="#research">So sánh training của 7 model →</a></div>`+
 `<div class="learn-bottom"><section class="panel"><span class="eyebrow">KẾT QUẢ → LẦN HỌC TỚI</span><h2>Data flywheel đóng vòng.</h2><p>Trace → kiểm giả thuyết → can thiệp/data → QA → học → kiểm lại.</p><a href="#architecture" class="button">Xem data flywheel →</a></section><section class="panel"><span class="eyebrow">ĐIỀU KIỆN CHỌN PHIÊN BẢN</span><h2>Robot tốt hơn mới có ý nghĩa.</h2><p>Kiểm cả task, regression và tổng công. Loss giảm chưa đủ.</p><a href="#validation">Xem phép kiểm →</a></section></div>`+
 `<details class="technical-detail"><summary>Đọc sâu: kiến trúc, loss và gradient routes</summary><div class="detail-body"><article class="document-reader">${renderMarkdown(DOSSIER.find(d=>d.path===ENGINEERING_DIR+'02-kien-truc-va-cach-hoc.md').markdown,ENGINEERING_DIR+'02-kien-truc-va-cach-hoc.md')}</article></div></details>`;
}
function initLearningCore(signal){const flow=document.querySelector('#learn-flow');if(!flow)return;let mode='run',source='R',selected=0,blocks=[];
 function showDetail(){const s=blocks[selected];document.querySelector('#learn-detail').innerHTML=`<div><span class="eyebrow">KHỐI 0${selected+1}</span><h2>${esc(s.title)}</h2></div><div><p>${esc(s.body)}</p><p class="learn-detail-output"><strong>Đầu ra:</strong> ${esc(s.output)}</p></div>`;flow.querySelectorAll('[data-learn-block]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.learnBlock)===selected)));}
 function draw(){const data=LEARNING_SOURCES[source];blocks=mode==='run'?LEARNING_RUN:[
 {title:data.title,tag:data.caption,visual:'input',body:data.limit+' Dataset release kiểm quyền, nhãn, clocks, masks và roots/splits trước train.',output:'Eligible samples + targets + provenance'},
 {title:'VLM & interface',tag:source==='H'?'FROZEN TRONG HUMAN PILOT':source==='V'?'CURRENT FRAMES + FUTURE TOKENS':'TRAIN / FREEZE THEO RECIPE',visual:'features',body:source==='H'?'VLM giữ trọng số ở cả R_common và R_common+H. Features vẫn thay đổi theo ảnh.':source==='V'?'Future-aware tokens học từ current context. Target encoder xử lý future frames ở nhánh training riêng, với stop-gradient. Frozen target encoder chưa là toàn VLM frozen.':'Image/text features là conditioning, không action labels. GR00T N1.5 official giữ VLM frozen; FluxVLA config mở visual có recipe riêng.',output:'Features + masks đúng native interface'},
 {title:source==='V'?'Học future alignment':'Học Action Expert',tag:source==='H'?'COMMON WRIST + SHARED TRUNK':source==='V'?'AUXILIARY LOSS · VIDEO KHÔNG ACTION':'NATIVE ROBOT ACTION OBJECTIVE',visual:source==='V'?'alignment':'action',body:source==='H'?'Common wrist-motion loss cập nhật shared trunk/common modules. Robot native loss vẫn học robot actions; human không cập nhật native decoder trực tiếp.':source==='V'?'FOCA-style implicit alignment là candidate tham khảo. Robot batches vẫn học action objective ở adaptation. Không gán robot-action loss cho video thiếu action; module routes phải port và kiểm riêng.':'Future robot actions được normalize, thêm noise để học flow velocity theo selected head; inference tích phân thành action chunk. Loss cập nhật chỉ params được mở.',output:source==='H'?'Human motion hypothesis để kiểm downstream':source==='V'?'Representation candidate → robot adaptation → rollout':'Candidate weights theo native action objective'},
 {title:'Lưu & kiểm candidate',tag:'RELOAD → ROLLOUT → EVALUATION',visual:'checkpoint',body:'Reload checkpoint, chạy controller, kiểm toàn task và regression. Chọn trên development; freeze trước final độc lập.',output:'Checkpoint + recipe + gain / no-gain report'}];
 flow.innerHTML=blocks.map((s,i)=>`<button type="button" class="learn-block" data-learn-block="${i}" aria-pressed="${selected===i}" aria-controls="learn-detail"><span class="learn-block-number">0${i+1}</span><div class="learn-visual">${learningVisual(s.visual,data.image)}</div><strong>${esc(s.title)}</strong><small>${esc(s.tag)}</small></button>`).join('');
 const targets=document.querySelector('#learn-targets');targets.hidden=mode!=='train';targets.innerHTML=source==='R'?`<span class="learn-target-label">TRAINING TARGET · KHÔNG VÀO CURRENT INPUT</span><div><strong>Future robot actions</strong><b>→</b><span>Normalize + noise</span><b>→</b><strong>Action loss</strong><b>→</b><span>Allowed params</span></div>`:source==='V'?`<span class="learn-target-label">FUTURE FRAMES · CHỈ DÙNG KHI TRAIN</span><div><strong>Later frames, cùng episode</strong><b>→</b><span>Frozen target encoder</span><b>→</b><strong>Future alignment loss</strong></div><small>Inference dùng current context. Generated video không cần pseudo-actions ở route này.</small>`:`<span class="learn-target-label">GEOMETRY TARGET · CUSTOM HUMAN PILOT</span><div><strong>Tracked future wrists</strong><b>→</b><span>Frame / time / masks</span><b>→</b><strong>Common motion loss</strong></div><small>Robot native action labels vẫn ở branch riêng; wrist người chưa là robot joints.</small>`;
 document.querySelector('#learn-source-controls').hidden=mode!=='train';document.querySelector('#learn-route').textContent=mode==='run'?'Robot state → Action Expert · Scorer chấm độc lập · Outcome → data flywheel':data.route;document.querySelectorAll('[data-learn-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.learnMode===mode)));document.querySelectorAll('[data-learn-source]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.learnSource===source)));showDetail();}
 document.querySelector('main').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.learnMode){mode=b.dataset.learnMode;selected=0;draw();}if(b.dataset.learnSource){source=b.dataset.learnSource;selected=0;draw();}if(b.dataset.learnBlock!==undefined){selected=Number(b.dataset.learnBlock);showDetail();}},{signal});draw();
}
